/**
 * GPU-accelerated point sampler for SDF volumes.
 *
 * **Architecture**
 * - Uses a pre-computed SDF (Signed Distance Field) to efficiently test volume containment.
 * - Employs **Blue Noise Sampling** for temporally stable, low-discrepancy point distribution.
 * - Supports **Rejection Sampling** on the GPU to conform to complex shapes.
 * - Outputs transformation matrices directly compatible with `THREE.InstancedMesh`.
 *
 * **Sampling Strategies**
 * - **Uniform**: Distributes points uniformly within the volume.
 * - **Surface**: (Planned) Distributes points near the surface.
 * - **Custom**: (Planned) Uses a custom density function.
 *
 * **Usage**
 * This class is typically used in conjunction with `ComputeSDFGenerator`.
 *
 * @example
 * import { ComputeSDFGenerator, ComputeBVHSampler } from '@three-blocks/core';
 * import * as THREE from 'three/webgpu';
 *
 * // 1. Generate SDF from geometry
 * const sdfGen = new ComputeSDFGenerator({ resolution: 64 });
 * await sdfGen.generate(geometry, bvh, renderer);
 *
 * // 2. Sample points inside the volume
 * const sampler = new ComputeBVHSampler(sdfGen, renderer, 10000, {
 *   strategy: 'uniform',
 *   sdfThreshold: 0.0,  // < 0 is inside
 *   samplingBounds: sdfGen.geometryBounds, // Tight bounds for efficiency
 *   maxAttempts: 32,    // Retry limit for rejection sampling
 *   alignToNormal: true // Align instances to SDF gradient
 * });
 *
 * // 3. Run compute shader
 * await sampler.compute();
 *
 * // 4. Use output with InstancedMesh
 * const instancedMesh = new THREE.InstancedMesh(geometry, material, 10000);
 * instancedMesh.instanceMatrix = sampler.output;
 *
 * @class ComputeBVHSampler
 * @short GPU sampler that rejects/accepts points inside an SDF volume and outputs instance matrices or positions.
 * @category Compute
 * @tags WebGPU
 * @see {@link ComputeSDFGenerator}
 */
export class ComputeBVHSampler {
    /**
     * Create a new BVH-based volume sampler.
     *
     * @param {ComputeSDFGenerator} sdfGenerator - The SDF generator containing the volume data.
     * @param {THREE.WebGPURenderer} renderer - WebGPU renderer instance.
     * @param {number} count - Total number of samples to generate.
     * @param {Object} [options] - Configuration options.
     * @param {string} [options.strategy='uniform'] - Distribution strategy: `'uniform'`, `'surface'`, or `'custom'`.
     * @param {number} [options.sdfThreshold=0.0] - SDF value threshold. Points with distance < threshold are accepted.
     *   - Negative values are inside the mesh.
     *   - Positive values are outside (for shells).
     * @param {number} [options.seed=1337] - Random seed for stable sampling.
     * @param {number} [options.maxAttempts=32] - Maximum rejection sampling attempts per instance per frame.
     * @param {number} [options.surfaceWeight=1.0] - Weight for surface-weighted sampling (when strategy='surface').
     * @param {boolean} [options.alignToNormal=false] - If true, aligns the Y-axis of instances to the SDF gradient (surface normal).
     * @param {THREE.Vector3} [options.scale=Vector3(1,1,1)] - Scale factor applied to each generated instance.
     */
    constructor(sdfGenerator: ComputeSDFGenerator, renderer: THREE.WebGPURenderer, count: number, options?: {
        strategy?: string;
        sdfThreshold?: number;
        seed?: number;
        maxAttempts?: number;
        surfaceWeight?: number;
        alignToNormal?: boolean;
        scale?: THREE.Vector3;
    });
    /** @type {ComputeSDFGenerator} */
    sdfGenerator: ComputeSDFGenerator;
    /** @type {THREE.WebGPURenderer} */
    renderer: THREE.WebGPURenderer;
    /** @type {number} */
    count: number;
    /** @type {string} */
    strategy: string;
    /** @type {boolean} */
    alignToNormal: boolean;
    /** @type {THREE.Box3 | null} */
    samplingBounds: THREE.Box3 | null;
    /** @private */
    private uSeed;
    /** @private */
    private uThreshold;
    /** @private */
    private uMaxAttempts;
    /** @private */
    private uSurfaceWeight;
    /** @private */
    private uInverseBoundsMatrix;
    /** @private */
    private uBoundsMatrix;
    /** @private */
    private uTexelSize;
    /** @private */
    private uSdfResolution;
    /** @private */
    private uScale;
    /** @private */
    private uSamplingMin;
    /** @private */
    private uSamplingMax;
    /** @type {THREE.StorageInstancedBufferAttribute} */
    outMatrixSSBO: THREE.StorageInstancedBufferAttribute;
    /** @type {THREE.StorageInstancedBufferAttribute} */
    outPositionsSSBO: THREE.StorageInstancedBufferAttribute;
    /** @private */
    private computeNode;
    /** @private */
    private _compiled;
    /**
     * Builds the compute shader for volume sampling.
     * Uses TSL Fn() to avoid ptr<storage, ...> parameters which Safari/Firefox reject.
     * @private
     */
    private _buildComputeShader;
    /**
     * Computes the volume sampling.
     *
     * @param {Object} [options] - Compute options
     * @param {number} [options.sdfThreshold] - Override SDF threshold
     * @param {boolean} [options.debug=false] - Enable debug logging
     * @returns {Promise<void>}
     */
    compute(options?: {
        sdfThreshold?: number;
        debug?: boolean;
    }): Promise<void>;
    /**
     * Updates the SDF generator reference (useful when SDF is regenerated).
     *
     * @param {ComputeSDFGenerator} sdfGenerator - New SDF generator
     */
    updateSDF(sdfGenerator: ComputeSDFGenerator): void;
    /**
     * Gets the output transformation matrices.
     * @returns {THREE.StorageInstancedBufferAttribute}
     */
    get output(): THREE.StorageInstancedBufferAttribute;
    /**
     * Gets the output positions buffer (vec3 per sample).
     * Useful for particle systems like SPH that only need positions.
     * @returns {THREE.StorageInstancedBufferAttribute}
     */
    get positionsBuffer(): THREE.StorageInstancedBufferAttribute;
    /**
     * Performs CPU readback of transformation matrices.
     * @returns {Promise<Float32Array>}
     */
    readback(): Promise<Float32Array>;
    readbackPositions(): Promise<Float32Array<any>>;
    /**
     * Calculates the valid sample rate (non-zero positions).
     * Accounts for potential vec4 padding in GPU buffers.
     * @param {Float32Array} positions - Positions array from readbackPositions()
     * @returns {number} Valid sample percentage (0-100)
     */
    calculateValidRate(positions: Float32Array): number;
    /**
     * Disposes GPU resources.
     */
    dispose(): void;
}
